#:property AllowUnsafeBlocks=true

using System;
using System.Runtime.InteropServices;

// Test stackalloc with Span<nint> and Span<nuint>
Span<nint> signed = stackalloc nint[4];
for (int i = 0; i < signed.Length; i++)
    signed[i] = (nint)(i * 10);

Span<nuint> unsigned = stackalloc nuint[4];
for (int i = 0; i < unsigned.Length; i++)
    unsigned[i] = (nuint)(i * 100);

Console.WriteLine($"nint size:  {sizeof(nint)} bytes ({sizeof(nint) * 8}-bit)");
Console.WriteLine($"nuint size: {sizeof(nuint)} bytes ({sizeof(nuint) * 8}-bit)");

Console.WriteLine();
Console.WriteLine("Span<nint>:");
for (int i = 0; i < signed.Length; i++)
    Console.WriteLine($"  [{i}] = {signed[i]}");

Console.WriteLine("Span<nuint>:");
for (int i = 0; i < unsigned.Length; i++)
    Console.WriteLine($"  [{i}] = {unsigned[i]}");

